
const SERENITY_DEFAULT_LOGO = "data:image/png;base64,";
function getSerenityLogo(){
  try{ return localStorage.getItem("serenity155CustomLogo") || SERENITY_DEFAULT_LOGO; }
  catch(e){ return SERENITY_DEFAULT_LOGO; }
}
function applySerenityLogo(){
  const src=getSerenityLogo();
  document.querySelectorAll('img[data-serenity-logo], .brand img, .footer-brand img, .hero-logo, .team-block img').forEach(img=>{
    if(img && (img.getAttribute('src')?.includes('serenity155-logo') || img.hasAttribute('data-serenity-logo'))) {
      img.src=src;
      img.setAttribute('data-serenity-logo','1');
    }
  });
}
document.addEventListener("DOMContentLoaded", applySerenityLogo);
window.addEventListener("storage",e=>{if(e.key==="serenity155CustomLogo")applySerenityLogo()});
